using Dapper;
using Microsoft.Data.Sqlite;
using POS.Core;
using POS.Infrastructure;
using Xunit;

namespace POS.Tests;
public sealed class AcceptanceTests : IDisposable
{
    readonly string directory=Path.Combine(Path.GetTempPath(),"pos-tests-"+Guid.NewGuid());
    readonly PosService service;
    string Database=>Path.Combine(directory,"pos.db");
    public AcceptanceTests(){service=new PosService(Database);}
    long Add(SaleUnit unit=SaleUnit.UNIT,StockMode mode=StockMode.EXACT,long price=100000,string name="Producto")=>service.SaveProduct(new(0,null,name,"Alimentos",unit,mode,price,null,true));
    long Stock(long id)=>service.Inventory().Single(x=>x.ProductId==id).QuantityBase!.Value;
    SqliteConnection Connection(){var c=new SqliteConnection($"Data Source={Database};Pooling=False;Foreign Keys=True");c.Open();return c;}
    [Fact] public void ExactSaleAndHistoricalPrice(){var id=Add();service.AdjustStock(id,10,false,"Compra");var sale=service.CompleteSale([new(id,3)],PaymentMethod.CASH);Assert.Equal(7,Stock(id));var p=service.Products().Single();service.SaveProduct(p with{PriceMinor=200000,Name="Nuevo nombre"});var line=Assert.Single(service.SaleItems(sale));Assert.Equal(300000,line.TotalMinor);Assert.Equal("Producto",line.Name);Assert.Equal(100000,line.UnitPriceMinor);}
    [Theory][InlineData(500,50000,9500)][InlineData(1500,150000,8500)] public void WeightPriceIsPerKg(long grams,long total,long remaining){var id=Add(SaleUnit.KG,StockMode.WEIGHT);service.AdjustStock(id,10000,false,"Compra");var sale=service.CompleteSale([new(id,grams)],PaymentMethod.TRANSFER);Assert.Equal(total,Assert.Single(service.SaleItems(sale)).TotalMinor);Assert.Equal(remaining,Stock(id));}
    [Fact] public void PackPriceIsPerPack(){var id=Add(SaleUnit.PACK);service.AdjustStock(id,5,false,"Compra");var sale=service.CompleteSale([new(id,2)],PaymentMethod.CARD);Assert.Equal(200000,Assert.Single(service.SaleItems(sale)).TotalMinor);Assert.Equal(3,Stock(id));}
    [Fact] public void ManualSaleDoesNotChangeStatusOrCreateMovement(){var id=Add(SaleUnit.KG,StockMode.MANUAL);service.SetManualStatus(id,ReplenishmentStatus.BAJO);service.CompleteSale([new(id,500)],PaymentMethod.OTHER);var stock=Assert.Single(service.Inventory());Assert.Null(stock.QuantityBase);Assert.Equal(ReplenishmentStatus.BAJO,stock.Status);Assert.Empty(service.Movements(id));}
    [Fact] public void MultiProductSaleIsAtomic(){var a=Add(name:"Uno");var b=Add(name:"Dos");service.AdjustStock(a,10,false,"Compra");service.AdjustStock(b,5,false,"Compra");var sale=service.CompleteSale([new(a,3),new(b,2)],PaymentMethod.CASH);Assert.Equal(2,service.SaleItems(sale).Count);Assert.Equal(7,Stock(a));Assert.Equal(3,Stock(b));}
    [Fact] public void FailureAfterFirstItemRollsBackEverything(){var a=Add(name:"Uno");var b=Add(name:"Dos");service.AdjustStock(a,10,false,"Compra");service.AdjustStock(b,10,false,"Compra");using(var c=Connection())c.Execute($"CREATE TRIGGER fail_second BEFORE INSERT ON sale_items WHEN NEW.product_id={b} BEGIN SELECT RAISE(ABORT,'simulated failure'); END;");Assert.Throws<SqliteException>(()=>service.CompleteSale([new(a,3),new(b,2)],PaymentMethod.CASH));Assert.Equal(10,Stock(a));Assert.Equal(10,Stock(b));using var db=Connection();Assert.Equal(0,db.ExecuteScalar<long>("SELECT count(*) FROM sales"));Assert.Equal(0,db.ExecuteScalar<long>("SELECT count(*) FROM sale_items"));Assert.Equal(0,db.ExecuteScalar<long>("SELECT count(*) FROM stock_movements WHERE movement_type='SALE'"));}
    [Fact] public void InsufficientStockRollsBackAndDuplicateLinesAreAggregated(){var id=Add();service.AdjustStock(id,5,false,"Compra");Assert.Throws<ArgumentException>(()=>service.CompleteSale([new(id,3),new(id,3)],PaymentMethod.CASH));Assert.Equal(5,Stock(id));Assert.Empty(service.Sales(DateTime.MinValue,DateTime.MaxValue));}
    [Fact] public void CancellationReversesExactlyOnce(){var id=Add();service.AdjustStock(id,10,false,"Compra");var sale=service.CompleteSale([new(id,3)],PaymentMethod.CASH);service.CancelSale(sale,"Error");Assert.Equal(10,Stock(id));Assert.Throws<ArgumentException>(()=>service.CancelSale(sale,"Otra vez"));Assert.Single(service.Movements(id),x=>x.Type=="SALE_REVERSAL");Assert.Equal("CANCELLED",Assert.Single(service.Sales(DateTime.UtcNow.AddDays(-1),DateTime.UtcNow.AddDays(1))).Status);}
    [Fact] public void BulkPricesMatchPreviewAndAreAudited(){Add();Add(name:"Otro");var preview=service.PreviewPrices("Alimentos",10,true,100);service.ApplyPrices(preview);Assert.All(service.Products(),p=>Assert.Equal(110000,p.PriceMinor));using var c=Connection();Assert.Equal(2,c.ExecuteScalar<long>("SELECT count(*) FROM price_changes"));Assert.Throws<ArgumentException>(()=>service.ApplyPrices(preview));}
    [Fact] public void StalePreviewRollsBackEarlierUpdates(){var a=Add(name:"A");var b=Add(name:"B");var preview=service.PreviewPrices("",10,true,1);var p=service.Products().Single(x=>x.Id==b);service.SaveProduct(p with{PriceMinor=200000});Assert.Throws<ArgumentException>(()=>service.ApplyPrices(preview));Assert.Equal(100000,service.Products().Single(x=>x.Id==a).PriceMinor);}
    [Fact] public void BackupRestoresDataAndPreservesPreviousDatabase(){var id=Add();service.AdjustStock(id,10,false,"Compra");var backup=Path.Combine(directory,"export.db");service.Backup(backup);service.CompleteSale([new(id,3)],PaymentMethod.CASH);service.Restore(backup);Assert.Equal(10,Stock(id));Assert.Empty(service.Sales(DateTime.UtcNow.AddDays(-1),DateTime.UtcNow.AddDays(1)));Assert.Single(Directory.GetFiles(directory,"*.before-restore-*.db"));}
    [Fact] public void InvalidBackupDoesNotChangeData(){Add();var bad=Path.Combine(directory,"bad.db");File.WriteAllText(bad,"invalid");Assert.Throws<SqliteException>(()=>service.Restore(bad));Assert.Single(service.Products());}
    [Fact] public void DailyBackupIsRepeatableAndRetained(){Add();var backups=Path.Combine(directory,"backups");service.DailyBackup(backups);service.DailyBackup(backups);Assert.Single(Directory.GetFiles(backups));}
    [Fact] public void InactiveAndNonPositiveQuantitiesAreRejected(){var id=Add();service.SetActive(id,false);Assert.Throws<ArgumentException>(()=>service.CompleteSale([new(id,1)],PaymentMethod.CASH));Assert.Throws<ArgumentException>(()=>service.CompleteSale([new(id,0)],PaymentMethod.CASH));}
    [Theory][InlineData("0.5",SaleUnit.KG,500)][InlineData("1.5",SaleUnit.KG,1500)][InlineData("2",SaleUnit.PACK,2)] public void QuantitiesConvertWithoutFloatingPoint(string value,SaleUnit unit,long expected)=>Assert.Equal(expected,Pricing.Quantity(decimal.Parse(value,System.Globalization.CultureInfo.InvariantCulture),unit));
    [Fact] public void FractionalPacksAndSubgramWeightsAreRejected(){Assert.Throws<ArgumentException>(()=>Pricing.Quantity(0.5m,SaleUnit.PACK));Assert.Throws<ArgumentException>(()=>Pricing.Quantity(0.0005m,SaleUnit.KG));Assert.Equal(1,Pricing.Total(1,500,SaleUnit.KG));}
    [Fact] public void IncompatibleModesAndNegativePricesAreRejected(){Assert.Throws<ArgumentException>(()=>Add(SaleUnit.PACK,StockMode.WEIGHT));Assert.Throws<ArgumentException>(()=>Add(price:-1));}
    [Fact] public void MinimumStockPersistsAndManualProductsRejectIt(){var id=Add();service.SetMinimumStock(id,3);Assert.Equal(3,service.Inventory().Single(x=>x.ProductId==id).MinimumBase);Assert.Throws<ArgumentException>(()=>service.SetMinimumStock(id,-1));var manual=Add(mode:StockMode.MANUAL,name:"Manual");Assert.Throws<ArgumentException>(()=>service.SetMinimumStock(manual,1));}
    [Fact] public void DuplicateCodesAreRejectedWithoutChangingProduct(){var id=service.SaveProduct(new(0,"ABC","Uno","",SaleUnit.UNIT,StockMode.EXACT,100,null,true));Assert.Throws<ArgumentException>(()=>service.SaveProduct(new(0," ABC ","Dos","",SaleUnit.UNIT,StockMode.EXACT,200,null,true)));Assert.Equal(id,Assert.Single(service.Products()).Id);}
    [Fact] public void FakeCompatibleVersionBackupIsRejected(){Add();var file=Path.Combine(directory,"fake.db");using(var c=new SqliteConnection($"Data Source={file};Pooling=False")){c.Open();c.Execute("PRAGMA user_version=1; CREATE TABLE products(id INTEGER);");}Assert.Throws<ArgumentException>(()=>service.Restore(file));Assert.Single(service.Products());}
    [Fact] public void ManualCancellationKeepsStatus(){var id=Add(mode:StockMode.MANUAL);service.SetManualStatus(id,ReplenishmentStatus.REPONER);var sale=service.CompleteSale([new(id,2)],PaymentMethod.CASH);service.CancelSale(sale,"Error");Assert.Equal(ReplenishmentStatus.REPONER,Assert.Single(service.Inventory()).Status);Assert.Empty(service.Movements(id));}
    [Fact] public void BackupCanBeOpenedInSeparateInstallation(){var id=Add();service.AdjustStock(id,10,false,"Compra");var sale=service.CompleteSale([new(id,3)],PaymentMethod.CASH);var exported=Path.Combine(directory,"export.db");service.Backup(exported);var second=new PosService(Path.Combine(directory,"second","pos.db"));second.Restore(exported);Assert.Equal(service.Products(),second.Products());Assert.Equal(service.Inventory(),second.Inventory());Assert.Equal(service.SaleItems(sale),second.SaleItems(sale));Assert.Equal(service.Movements(id),second.Movements(id));}
    public void Dispose(){Directory.Delete(directory,true);}
}
